select edu_course_package_exam.id as id, edu_course_package_exam.clazz_id, edu_course_package_exam.course_id, edu_course.is_deleted as course_is_delete, edu_course_package_exam.kpoint_id, edu_course_kpoint.is_deleted as kpoint_is_delete, edu_course_package_exam.custom_exampaper_name, edu_course_package_exam.status, edu_course_package_exam.exampaper_id ,edu_course_package_exam.sort , exam_exampaper.name as exam_name, exam_exampaper.is_deleted as exampaper_is_delete, exam_exampaper.subjectId exam_subject_id,exam_exampaper.type exam_type
from edu_course_package_exam left join exam_exampaper on edu_course_package_exam.exampaper_id = exam_exampaper.id left join edu_course on edu_course_package_exam.course_id = edu_course.id left join edu_course_kpoint on edu_course_package_exam.kpoint_id = edu_course_kpoint.id
edu_course_package_exam.is_deleted=0 and exam_exampaper.id is not null
and edu_course_package_exam.clazz_id = #{coursePackageExam.clazzId}
and edu_course_package_exam.kpoint_id = #{coursePackageExam.kpointId}
and edu_course_package_exam.course_id = #{coursePackageExam.courseId}
and exam_exampaper.type = #{coursePackageExam.examType}
and exam_exampaper.subjectId = #{coursePackageExam.examSubjectId}
and exam_exampaper.type = #{coursePackageExam.examType}
and exam_exampaper.name like concat('%',#{coursePackageExam.examName},'%')
order by edu_course_package_exam.sort desc

